\label{lem:monic}
Let $w$ be an integrable weight that is positive almost everywhere on
$(-1,1)$. There is a unique real monic polynomial $q_n$ of degree $n$
minimizing $\int_{-1}^1|q(t)|w(t)\,dt$. Its zeros are simple and lie
in $(-1,1)$, and
\begin{equation}\label{eq:orthog}
 \int_{-1}^1p(t)\operatorname{sgn} q_n(t)w(t)\,dt=0,
 \qquad \deg p<n.
\end{equation}
If $w$ is even, then $q_n(-t)=(-1)^nq_n(t)$.

\label{thm:BohrAllDimensions}
Let $d\geq2$ and $n\geq1$ be integers, and let $p_{n-1,d}$ interpolate $G_d$ at the zeros of $q_{n,d}$. Then $p_{n-1,d}$ is a best $L^1(\mu_d)$ approximant to $G_d$ among polynomials of degree at most $n-1$, and
\begin{equation}\label{eq:BohrAllDimensions}
 \begin{aligned}
 H(n,S^d)
 &=\int_{-1}^1|G_d(t)-p_{n-1,d}(t)|\,d\mu_d(t)\\
 &=\int_{-1}^1G_d(t)\operatorname{sgn} q_{n,d}(t)\,d\mu_d(t).
 \end{aligned}
\end{equation}
In particular, this is the sharp constant in
\[
 \left\|f\right\|_\infty\leq H(n,S^d)\left\|\Delta_{S^d}f\right\|_\infty
\]
for smooth functions $f\perp\mathcal H_{<n}$, at each fixed $n$.

For a fixed pole $e$, let $f_{n,d}$ be the mean-zero weak solution of
\begin{equation}\label{eq:generalBohrExtremal}
 -\Delta_{S^d}f_{n,d}(\omega)=\operatorname{sgn} q_{n,d}(e\cdot\omega).
\end{equation}
It has no harmonics of degrees less than $n$, and
\begin{equation}\label{eq:generalBohrExtremalValue}
 f_{n,d}(e)=\left\|f_{n,d}\right\|_\infty=H(n,S^d).
\end{equation}
Its smooth regularizations prove sharpness also in the smooth class defining the constant.

\label{prop:evenGreenStructure}
For an integer $s\geq1$, the mean-zero Green kernel on $S^{2s}$ is
\begin{equation}\label{eq:evenGreenStructure}
 G_{2s}(t)=\sum_{j=1}^{s-1}\frac{b_j}{(1-t)^j}
 -\frac1{2s-1}\log\frac{1-t}{2}+C_s.
\end{equation}
The constant $C_s$ makes the mean zero. When $s\geq2$, the coefficients of the pole terms are positive and satisfy
\begin{equation}\label{eq:evenGreenRecurrence}
 b_1=\frac1{2s-1},\qquad
 b_j=\frac{2(j-1)(s-j)}{j(2s-j-1)}b_{j-1},\qquad 2\leq j\leq s-1.
\end{equation}
For $s=1$ the sum is empty and $C_1=-1$.

\label{thm:trigGreenApproximation}
For a positive integer $n$, let $t_n$ be the sine polynomial of degree at most $n$ which interpolates $\mathcal G_2$ at
\begin{equation}\label{eq:uniformGreenNodes}
 \theta_j=\frac{j\pi}{n+1},\qquad j=1,\ldots,n.
\end{equation}
Then $t_n$ is a best $L^1(-\pi,\pi)$ approximant among all trigonometric polynomials of degree at most $n$. Its error is
\begin{equation}\label{eq:trigGreenBestError}
 \inf_{t\in T_n}\int_{-\pi}^{\pi}|\mathcal G_2(\theta)-t(\theta)|\,d\theta
 =8\sum_{j=0}^{\infty}
 \frac{1}{(2j+1)\bigl((n+1)^2(2j+1)^2-1\bigr)}.
\end{equation}
Away from the interpolation nodes, the error has the sign of $\sin((n+1)\theta)$ on $(0,\pi)$.

\label{thm:sphere2}
For every positive integer $n$,
\begin{equation}\label{eq:H22fixed}
 H(n,S^2)=2\sum_{j=0}^{\infty}\frac{1}{(2j+1)\bigl((n+1)^2(2j+1)^2-1\bigr)}.
\end{equation}
Consequently,
\begin{equation}\label{eq:H22}
 H(S^2)=\lim_{n\to\infty}n^2H(n,S^2)=\frac74\zeta(3).
\end{equation}
In particular, every smooth function $f$ on $S^2$ with $f\perp\mathcal H_{<n}$ and $\left\|\Delta f\right\|_\infty\leq1$ satisfies
\begin{equation}\label{eq:S2Bohr}
 \left\|f\right\|_\infty\leq\frac{7\zeta(3)}{4n^2},
\end{equation}
and the coefficient $7\zeta(3)/4$ cannot be decreased uniformly in $n$.

\label{thm:S3fixedn}
For a positive integer $n$, let $p_{n-1}$ interpolate $G_3$ at the zeros of $q_n$. Then $p_{n-1}$ is a best $L^1(\mu_3)$ approximant to $G_3$ among polynomials of degree at most $n-1$, and
\begin{equation}\label{eq:sharp-sign}
 \begin{aligned}
 H(n,S^3)&=\int_{-1}^1|G_3(t)-p_{n-1}(t)|\,d\mu_3(t)\\
 &=\int_{-1}^1G_3(t)\operatorname{sgn} q_n(t)\,d\mu_3(t).
 \end{aligned}
\end{equation}

\label{prop:S3reciprocal}
For every positive integer $m$,
\begin{equation}\label{eq:S3finiteReciprocal}
 H(2m,S^3)=\frac{\ell_m}{4\pi}
 \int_0^\infty\frac{d\eta}{P_m(i\eta)}.
\end{equation}

\label{thm:S3asymptotic}
The exact constants in Theorem~\ref{thm:S3fixedn} satisfy
\begin{equation}\label{eq:limit3}
 \lim_{n\to\infty}n^2H(n,S^3)=\beta.
\end{equation}

\label{prop:convergence}
The functions $F_n$ converge to $\varphi$ locally uniformly on $\mathbb C$.
In addition,
\begin{equation}\label{eq:mass}
 m_n:=\int_{-\pi n/2}^{\pi n/2}|F_n(x)|\,dx\longrightarrow M,
\end{equation}
and their mass on these expanding intervals is tight:
\begin{equation}\label{eq:tight}
 \lim_{R\to\infty}\limsup_{n\to\infty}
 \int_{R<|x|\leq\pi n/2}|F_n(x)|\,dx=0.
\end{equation}

\label{thm:main}
For every positive integer $n$,
\begin{equation}\label{eq:H23}
 n^2H(n,S^3)\leq\beta.
\end{equation}
Consequently $H(S^3)=\beta$.

\label{lem:B}
The function $B$ is even, entire, and of exponential type at most
one. For $x>0$,
\begin{equation}\label{eq:Berror}
 \frac1x-B(x)=\frac2\pi\varphi(x)
 \int_0^\infty\frac{dy}{(x^2+y^2)\varphi(iy)}.
\end{equation}
The radial function
\begin{equation}\label{eq:K}
 \mathcal K(u)=\frac1{4\pi}\left(\frac1{|u|}-B(|u|)\right),
 \qquad u\in\mathbb R^3,
\end{equation}
belongs to $L^1(\mathbb R^3)$ and satisfies
\begin{equation}\label{eq:Kfacts}
 \left\|\mathcal K\right\|_1=\beta,\qquad
 \widehat{\mathcal K}(\xi)=|\xi|^{-2}\quad\text{for }|\xi|\geq1.
\end{equation}
Here $\widehat h(\xi)=\int h(u)e^{-iu\cdot\xi}\,du$.

\label{lem:generalEndpointMinimum}
Among $T\in\mathcal T_n'$ with $T(0)=1$, the function $Q_{n,d}$ minimizes
\begin{equation}\label{eq:generalEndpointNorm}
 J_d(T)=\int_{-\pi/2}^{\pi/2}|T(\theta)|\,|\sin\theta|^{d-3}\,d\theta.
\end{equation}
Moreover, $\left\|Q_{n,d}\right\|_\infty=1$ on the real line, and $|F_{n,d}(z)|\leq e^{|\operatorname{Im}z|}$ for every $z\in\mathbb C$.

\label{prop:weightedEndpointConvergence}
For each fixed $d\geq3$, the functions $F_{n,d}$ converge to $\Phi_d$ locally uniformly on $\mathbb C$. For every real $b$ with $0\leq b\leq d-3$,
\begin{equation}\label{eq:weightedMomentConvergence}
 n^{b+1}\int_{-\pi/2}^{\pi/2}|Q_{n,d}(\theta)|\,|\sin\theta|^b\,d\theta
 \longrightarrow\int_\mathbb R|\Phi_d(x)|\,|x|^b\,dx.
\end{equation}
In particular, $n^{d-2}J_d(Q_{n,d})\longrightarrow M_d$.

\label{lem:generalOutsideIntegral}
For each fixed $d\geq3$, as $n\to\infty$,
\begin{equation}\label{eq:generalOutsideIntegral}
 \int_1^\infty\frac{a\,q_{n,d}(1)}{q_{n,d}(a)}\,da=O(n^{-2}).
\end{equation}

\label{thm:BohrLimitsFourSix}
With the extremal functions and minimum values defined in~\eqref{eq:weightedEntireMinimum},
\begin{equation}\label{eq:BohrLimitsFourSix}
 \begin{aligned}
 \lim_{n\to\infty}n^2H(n,S^4)&=\frac{M_4}{4},\\
 \lim_{n\to\infty}n^2H(n,S^6)
 &=\frac1{16}\left(2\int_\mathbb R|\Phi_6(x)|\,|x|\,dx-M_6\Phi_6''(0)\right).
 \end{aligned}
\end{equation}

\label{thm:evenBohrUniform}
For $d=4$ and $d=6$,
\begin{equation}\label{eq:evenBohrSupremum}
 H(S^d)=\sup_{n\geq1}n^2H(n,S^d)
 =\lim_{n\to\infty}n^2H(n,S^d)=\beta_d.
\end{equation}
For every positive integer $n$, the finite value $n^2H(n,S^d)$ is strictly smaller than $\beta_d$. On $S^4$ we also have the quantitative estimate
\begin{equation}\label{eq:S4QuantitativeBohr}
 n^2H(n,S^4)\leq\beta_4\frac{(n+1)^2}{n(n+3)}.
\end{equation}
Consequently, every smooth $f\perp\mathcal H_{<n}$ on either sphere satisfies $\left\|f\right\|_\infty\leq\beta_d n^{-2}\left\|\Delta f\right\|_\infty$, and the coefficient $\beta_d$ cannot be decreased uniformly in $n$.

\label{lem:gapTransfer}
Fix integers $d\geq2$ and $n\geq1$, and put $s_n(t)=\operatorname{sgn} q_{n,d}(t)$. For an even integer $m\geq2$, set
\begin{equation}\label{eq:transferParameters}
 \varepsilon=m^{-2},\qquad c=1-\varepsilon,\qquad
 b=\frac{(d-1)c}{3(n+d-1)-(d-1)c}.
\end{equation}
Define
\begin{equation}\label{eq:mobiusSource}
 h_b(t)=\left(\frac{1+b}{1+bt}\right)^{n+d-1}
 s_n\!\left(\frac{t+b}{1+bt}\right),
\end{equation}
and, for $0<\theta<\pi$, define the zonal source
\begin{equation}\label{eq:dilatedSource}
 g_{m,n}(\cos\theta)=h_b(\cos(m\theta))
 \left(\frac{|\sin(m\theta)|}{m\sin\theta}\right)^{d-1}.
\end{equation}
Then $\left\|g_{m,n}\right\|_\infty\leq1$, and $g_{m,n}\perp\mathcal H_{<mn}$ on $S^d$.

\label{thm:optimalLinearS2}
For each positive integer $n$,
\begin{equation}\label{eq:optimalLinearS2}
 \inf_A\sup\left\{\left\|f-Af\right\|_\infty:\;\left\|\Delta f\right\|_\infty\leq1\right\}=H(n,S^2),
\end{equation}
where the supremum is taken over smooth complex-valued functions on $S^2$ and the infimum over linear operators $A:C^\infty(S^2)\to\mathcal H_{<n}$. The infimum is attained by the method obtained from the best $L^1$ approximant to $G_2$, with constants reproduced exactly.

\label{thm:strictFavardS2}
For each integer $n\geq2$,
\begin{equation}\label{eq:strictFavardS2}
 K(n,S^2)<H(n,S^2).
\end{equation}

\label{prop:explicitFavardGapS2}
For every integer $n\geq32$,
\begin{equation}\label{eq:explicitFavardGapS2}
 K(n,S^2)\leq H(n,S^2)-\frac{0.000000238}{n^7}.
\end{equation}
For the concrete case $n=3$, we have
\begin{equation}\label{eq:explicitFavardGapThree}
 K(3,S^2)\leq H(3,S^2)-0.00000000144.
\end{equation}
Both estimates apply to complex-valued functions. The decimal constants are chosen below the bounds obtained in the proof, so the displayed inequalities do not depend on numerical rounding.

\label{thm:strictFavard}
For each integer $n\geq2$,
\begin{equation}\label{eq:strictFavard}
 K(n,S^3)<H(n,S^3).
\end{equation}

Let $p_{n-1,3}$ be the interpolating polynomial constructed for $G_3$, and put $R_{n,3}=G_3-p_{n-1,3}$. The kernel computation gives
\begin{equation}\label{eq:residualNorm}
 \int_{S^3}|R_{n,3}(x\cdot y)|\,d\sigma_3(y)=H(n,S^3)
\end{equation}
for every pole $x$, and $\operatorname{sgn} R_{n,3}=\operatorname{sgn} q_n$ almost everywhere. The zeros of $q_n$ are simple and lie in $(-1,1)$. Annihilation of the polynomial part and~\eqref{eq:exactFavardDuality} give
\begin{equation}\label{eq:dualResidualBound}
 K(n,S^3)\leq\sup_{\mu\in\mathcal M_n}\left\|U_\mu\right\|_1\leq H(n,S^3).
\end{equation}
Since $G_3$ is integrable, the continuous-kernel approximation used in the proof of Theorem~\ref{thm:strictFavardS2} again shows that the supremum over measures is attained.

Equality would force the rotated sign functions $\operatorname{sgn} R_{n,3}(x\cdot y)$ to agree up to a constant phase for almost every pole with respect to $|\mu|$. Their sign-change sets are now two-dimensional latitude spheres. For nonparallel poles, the intersection of two such latitude spheres has dimension at most one, so finitely many intersections cannot cover a latitude sphere. The same neighborhood argument as on $S^2$ therefore forces $\mu$ to be supported on one antipodal pair. Annihilation of the constant and the linear function along that axis makes both masses zero, contradicting total variation one. Thus the second inequality in~\eqref{eq:dualResidualBound} is strict, proving~\eqref{eq:strictFavard}.
